# 数据源坏点修正（按 cities.js 全名）：大同/甘南/兴安条目坐标张冠李戴，新北为常州值
OVERRIDES = {
    "大同市": 40.08, "甘南藏族自治州": 34.98, "兴安盟": 46.08,
    "新北市": 25.01, "海南藏族自治州": 36.28, "克孜勒苏柯尔克孜自治州": 39.72,
    "海北藏族自治州": 36.95, "黄南藏族自治州": 35.52, "果洛藏族自治州": 34.47,
    "海南黎族苗族自治州": 19.25,  # 若列为海南州错指青海时兜底（不应出现）
}
ALIAS = {  # 数据源旧名/简称 → cities.js 名称
    "襄樊": "襄阳市", "巢湖": "芜湖市", "莱芜": "济南市",
}

ETH = ["自治州", "地区", "盟", "矿区"]
ETHN_RE = re.compile(
    r"(汉|蒙古|回|藏|维吾尔|苗|彝|壮|布依|朝鲜|满|侗|瑶|白|土家|哈尼|哈萨克|傣|黎|傈僳|佤|畲|高山|拉祜|水|东乡|纳西|景颇|柯尔克孜|土|达斡尔|仫佬|羌|布朗|撒拉|毛南|仡佬|锡伯|阿昌|普米|塔吉克|怒|乌孜别克|俄罗斯|鄂温克|德昂|保安|裕固|京|塔塔尔|独龙|鄂伦春|赫哲|门巴|珞巴|基诺)族")

# 转录漏项与数据源缺项（市名 → 纬度）
EXTRA = {
    "宁波市": 29.87, "东营市": 37.43, "南阳市": 32.99, "襄阳市": 32.04,
    "中山市": 22.52, "铜仁市": 27.73, "普洱市": 22.79, "资阳市": 30.12,
    "三沙市": 16.83, "儋州市": 19.52, "襄樊": 32.04,
}


def norm(n):
    n = re.sub(r"(市|地区|盟|矿区)$", "", n)
    if "自治州" in n:
        n = n.split("自治州")[0]
    n = ETHN_RE.sub("", n)
    # 「博尔塔拉蒙古自治州」式：族字缺省的裸民族后缀（循环剥）
    bare = (r"(蒙古|回|藏|维吾尔|苗|彝|壮|布依|朝鲜|满|侗|瑶|白|土家|哈尼|哈萨克|傣|黎|傈僳|佤|拉祜|"
            r"水|纳西|景颇|柯尔克孜|土|达斡尔|仫佬|羌|布朗|撒拉|毛南|仡佬|锡伯|阿昌|普米|塔吉克|怒|"
            r"乌孜别克|鄂温克|德昂|保安|裕固|塔塔尔|独龙|鄂伦春|门巴|珞巴|基诺)$")
    for _ in range(3):
        n2 = re.sub(bare, "", n)
        if n2 == n:
            break
        n = n2
    return n


def main():
    data = {}
    for item in RAW.split("|"):
        p = item.split()
        if len(p) == 3:
            data[p[0]] = (float(p[1]), float(p[2]))
    for short, full in ALIAS.items():
        if short in data:
            data[norm(full)] = data.pop(short)
    for full, lat in EXTRA.items():
        data.setdefault(norm(full), (None, lat))

    src = open(os.path.join(ASSETS, "cities.js"), encoding="utf-8").read()
    bak = src
    open(os.path.join(ASSETS, "cities.js.bak"), "w", encoding="utf-8").write(bak)

    unmatched = []

    def lat_of(full, lon):
        if full in OVERRIDES:
            return OVERRIDES[full]
        k = norm(full)
        if k in data and data[k][1] is not None:
            return data[k][1]
        for dk, dv in data.items():
            if norm(dk) == k and dv[1] is not None:
                return dv[1]
        unmatched.append(full)
        return None

    def repl(m):
        name, lon = m.group(1), m.group(2)
        lat = lat_of(name, float(lon))
        if lat is None:
            return m.group(0)
        return "['%s', %s, %.2f]" % (name, lon, lat)

    out = re.sub(r"\['([^']+)',\s*([\d.]+)\]", repl, src)
    header = ("/* cities.js —— 全国省级行政区与地级行政区（含驻地经纬度）\n"
              "   经纬度取政府驻地约值，精度 0.01°（纬度供古法日出日落定时辰用，\n"
              "   0.01° 经差≈24 秒、纬度对日出的影响 <10 秒/0.01°）。\n"
              "   纬度数据源 github.com/88250/city-geo（BD-09 坐标，误差忽略）。 */\n")
    out = re.sub(r"^/\*.*?\*/\n", header, out, count=1, flags=re.S)
    open(os.path.join(ASSETS, "cities.js"), "w", encoding="utf-8").write(out)
    print("unmatched:", unmatched if unmatched else "无")
    n = len(re.findall(r",\s*\d+\.\d+\]", out))
    print("已补纬度城市数:", n)


if __name__ == "__main__":
    main()
